function bulkSongReleasePanel(){const songs=records.filter(r=>r.type==='songs').sort((a,b)=>a.name.localeCompare(b.name,'ja'));const releases=records.filter(r=>r.type==='releases').sort((a,b)=>a.name.localeCompare(b.name,'ja'));return '<section class="card section"><h3>収録作品の一括変更</h3><p class="note">変更する楽曲にチェックを入れ、収録作品を選んでください。選んでいない楽曲は変更されません。</p><div class="toolbar"><input id="bulkSongSearch" type="search" placeholder="曲名で検索" aria-label="一括変更する楽曲を検索"><select id="bulkSongReleaseFilter" aria-label="現在の収録作品で絞り込み"><option value="all">すべての収録作品</option><option value="none">未設定</option>'+releases.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+'</option>').join('')+'</select></div><div class="toolbar"><button type="button" class="outline" id="bulkSongAll">表示中を選択</button><button type="button" class="outline" id="bulkSongNone">選択解除</button><span id="bulkSongCount">0曲選択</span><span id="bulkSongVisibleCount" class="note">'+songs.length+'曲表示</span></div><div class="bulk-song-list">'+songs.map(r=>'<label class="bulk-song-row" data-song-name="'+esc(r.name.toLocaleLowerCase())+'" data-release-id="'+esc(r.releaseId||'')+'"><input type="checkbox" class="bulk-song-check" value="'+esc(r.id)+'"> <span>'+esc(r.name)+' <small>（'+esc(releases.find(x=>x.id===r.releaseId)?.name||'未設定')+'）</small></span></label>').join('')+'</div><label>変更先の収録作品<select id="bulkSongTarget"><option value="">未設定にする</option>'+releases.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+'</option>').join('')+'</select></label><div class="toolbar"><button type="button" class="primary" id="bulkSongApply">変更内容をプレビュー</button></div><div id="bulkSongPreview" class="bulk-song-preview" hidden></div>'+(lastBulkSongChange()?'<div class="bulk-song-preview"><h4>直前の一括変更</h4><p class="note">'+esc(lastBulkSongChange().songs.length)+'曲の変更を元に戻せます。別の編集が入った曲は上書きしません。</p><button type="button" class="outline" id="bulkSongUndo">直前の一括変更を取り消す</button></div>':'')+'</section>'}
function listPage(type){const rows=records.filter(r=>r.type===type);const years=[...new Set(rows.map(r=>date(r).slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse();const facetKey=type==='releases'?'kind':type==='shows'?'tour':type==='members'?'role':'genre';const facets=[...new Set(rows.map(r=>String(r[facetKey]||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja'));const sortOptions=[['date-desc','日付：新しい順'],['date-asc','日付：古い順'],['name-asc','名前：あいうえお順'],['name-desc','名前：逆順'],...(type==='releases'?[['sales-desc','売上枚数：多い順'],['sales-asc','売上枚数：少ない順']]:[]),...(type==='shows'?[['attendance-desc','動員数：多い順'],['attendance-asc','動員数：少ない順'],['revenue-desc','興行収入：多い順'],['revenue-asc','興行収入：少ない順']]:[])];const facetName=type==='releases'?'作品形態':type==='shows'?'ツアー':type==='members'?'担当パート':'ジャンル';const options=(values,selected)=>values.map(v=>'<option value="'+esc(v)+'" '+(v===selected?'selected':'')+'>'+esc(v)+'</option>').join('');return '<div class="eyebrow">ARCHIVE / '+esc(type.toUpperCase())+'</div><h1>'+esc(TYPES[type])+'アーカイブ</h1><div class="toolbar"><button class="primary" data-go="form" data-type="'+esc(type)+'">＋ 新規登録</button>'+(type==='songs'?'<button type="button" class="outline" id="exportVisibleSongs">表示中をCSV保存</button><button type="button" class="outline" id="exportAllSongs">全曲をCSV保存</button>':type==='releases'?'<button type="button" class="outline" id="exportVisibleReleases">表示中をCSV保存</button><button type="button" class="outline" id="exportAllReleases">全作品をCSV保存</button>':type==='shows'?'<button type="button" class="outline" id="exportVisibleShows">表示中をCSV保存</button><button type="button" class="outline" id="exportAllShows">全ライブをCSV保存</button>':type==='members'?'<button type="button" class="outline" id="exportVisibleMembers">表示中をCSV保存</button><button type="button" class="outline" id="exportAllMembers">全メンバーをCSV保存</button>':type==='bands'?'<button type="button" class="outline" id="exportVisibleBands">表示中をCSV保存</button><button type="button" class="outline" id="exportAllBands">全バンドをCSV保存</button>':type==='events'?'<button type="button" class="outline" id="exportVisibleEvents">表示中をCSV保存</button><button type="button" class="outline" id="exportAllEvents">全出来事をCSV保存</button>':'')+'</div><div class="toolbar"><input id="filter" class="search" placeholder="名前・説明・詳細項目を検索" value="'+esc(filter)+'" aria-label="一覧検索" style="flex:1;min-width:160px"><button type="button" class="outline" id="clearArchiveKeyword">検索語を消す</button></div><div class="toolbar"><label>年 <select id="archiveYear"><option value="">すべての年</option>'+options(years,archiveYear)+'</select></label><label>'+esc(facetName)+' <select id="archiveFacet"><option value="">すべて</option>'+options(facets,archiveFacet)+'</select></label><label>並べ替え <select id="archiveSort">'+sortOptions.map(([v,label])=>'<option value="'+v+'" '+(archiveSort===v?'selected':'')+'>'+label+'</option>').join('')+'</select></label><button type="button" class="outline" id="clearArchiveFilters">条件を解除</button></div><div class="toolbar" role="group" aria-label="一覧の表示形式"><button type="button" class="'+(archiveLayout==='list'?'primary':'outline')+'" data-layout="list" aria-pressed="'+(archiveLayout==='list')+'">☰ リスト</button><button type="button" class="'+(archiveLayout==='grid'?'primary':'outline')+'" data-layout="grid" aria-pressed="'+(archiveLayout==='grid')+'">▦ グリッド</button></div><div class="toolbar"><label>表示件数 <select id="archiveLimit"><option value="all" '+(archiveLimit==='all'?'selected':'')+'>すべて</option>'+[10,25,50,100].map(n=>'<option value="'+n+'" '+(archiveLimit===String(n)?'selected':'')+'>'+n+'件</option>').join('')+'</select></label><button type="button" class="outline" id="resetArchiveLimit">表示件数を初期化</button></div><p id="archiveCount" class="note" role="status" aria-live="polite" aria-atomic="true" aria-label="アーカイブの表示件数と検索結果件数" aria-relevant="text" title="検索・絞り込み条件に応じた表示件数">'+Math.min(archiveFiltered(type).length,archiveLimit==='all'?Infinity:Number(archiveLimit))+'件表示 / 一致'+archiveFiltered(type).length+'件 / 全'+rows.length+'件'+(archiveLimit!=='all'&&archiveFiltered(type).length>Number(archiveLimit)?'（残り'+(archiveFiltered(type).length-Number(archiveLimit))+'件・下の「残りをすべて表示」ボタンから確認できます）':'')+'</p><button type="button" class="outline" id="showAllArchive" aria-label="残り'+(archiveLimit==='all'?0:Math.max(0,archiveFiltered(type).length-Number(archiveLimit)))+'件の検索結果をすべて表示" title="現在の検索条件を維持して残り'+(archiveLimit==='all'?0:Math.max(0,archiveFiltered(type).length-Number(archiveLimit)))+'件を表示" '+(archiveLimit==='all'||archiveFiltered(type).length<=Number(archiveLimit)?'hidden':'')+'>残り'+(archiveLimit==='all'?0:Math.max(0,archiveFiltered(type).length-Number(archiveLimit)))+'件をすべて表示</button><div id="listResults">'+archiveResultsHtml(archiveLimit==='all'?archiveFiltered(type):archiveFiltered(type).slice(0,Number(archiveLimit)))+'</div>'}
function gridItems(arr){if(!arr.length)return '<div class="empty">該当するデータがありません。</div>';return '<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px">'+arr.map(r=>{const photo=featuredPhoto(r)||(r.type==='releases'&&/^https:\/\//i.test(r.coverUrl||'')?r.coverUrl:'');const art=photo&&/^(https:\/\/|data:image\/jpeg;base64,)/i.test(photo)?'<img src="'+esc(photo)+'" alt="'+esc(title(r))+'の画像" loading="lazy" style="display:block;width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px 10px 0 0" onerror="this.style.display=\'none\'">':'<div aria-hidden="true" style="aspect-ratio:1;display:grid;place-items:center;font-size:46px;background:rgba(190,160,90,.1)">♫</div>';return '<button type="button" data-detail="'+esc(r.id)+'" style="text-align:left;min-width:0;padding:0;border:1px solid rgba(190,160,90,.3);border-radius:12px;overflow:hidden;background:transparent;color:inherit;cursor:pointer">'+art+'<div style="padding:10px"><strong style="display:block;overflow-wrap:anywhere">'+esc(title(r))+'</strong><small>'+esc(date(r)||'日付未設定')+'</small></div></button>'}).join('')+'</div>'}
function listItems(arr){if(archiveLayout==='grid')return gridItems(arr);return arr.length?arr.map(r=>{const release=r.type==='songs'&&r.releaseId?records.find(x=>x.type==='releases'&&x.id===r.releaseId):null;const related=r.type==='releases'?linkedSongs(r):[];const image=featuredPhoto(r)||(r.type==='releases'&&/^https:\/\//i.test(r.coverUrl||'')?r.coverUrl:'');const thumb=image&&/^(https:\/\/|data:image\/jpeg;base64,)/i.test(image)?`<img src="${esc(image)}" alt="${esc(title(r))}の画像" loading="lazy" style="width:76px;height:76px;object-fit:cover;border-radius:10px;flex-shrink:0;border:1px solid rgba(190,160,90,.35)" onerror="this.style.display='none'">`:`<div aria-hidden="true" style="width:76px;height:76px;flex-shrink:0;display:grid;place-items:center;border-radius:10px;background:rgba(190,160,90,.1);font-size:26px">${r.type==='releases'?'♫':r.type==='shows'?'♬':'♪'}</div>`;return `<div class="item" style="align-items:center;gap:12px">${thumb}<div style="min-width:0;flex:1"><strong>${esc(title(r))}</strong><small>${esc(date(r)||'日付未設定')} ${r.kind?'・'+esc(r.kind):''}</small>${r.type==='songs'?'<div class="pill">収録作品：'+esc(release?.name||(r.releaseId?'作品が見つかりません':'未設定'))+'</div>':''}${r.type==='releases'?'<div class="pill">関連楽曲：'+related.length+'曲</div>'+ (related.length?'<p class="muted">'+related.map(x=>esc(x.name)).join(' / ')+'</p>':''):''}<p class="muted">${esc((r.description||r.role||r.venue||'').slice(0,120))}</p></div><button class="outline" data-detail="${esc(r.id)}">詳細を見る</button></div>`}).join(''):'<div class="empty">該当するデータがありません。</div>'}
function localPhotoEditor(r){const photos=Array.isArray(r.localPhotos)?r.localPhotos:[];const urls=String(r.photoUrls||'').split(/\r?\n/).map(x=>x.trim()).filter(x=>/^https:\/\//i.test(x));const current=Number.isInteger(r.featuredPhotoIndex)?r.featuredPhotoIndex:-1;const choices=[...urls,...photos];return '<section class="section card"><h2>写真と代表画像</h2><p class="note">写真を選ぶと縮小して端末内に保存します（最大8枚）。代表画像は下の写真から設定できます。</p><input id="localPhotoInput" type="file" accept="image/*" multiple aria-label="写真を選択"><div id="localPhotoStatus" class="note"></div>'+choices.map((p,i)=>'<div class="item"><img src="'+esc(p)+'" alt="写真'+(i+1)+'" style="width:64px;height:64px;object-fit:cover;border-radius:8px"><div><button type="button" class="outline" data-featured-photo="'+i+'" '+(current===i?'disabled':'')+'>'+(current===i?'★ 代表画像':'代表画像にする')+'</button>'+(i>=urls.length?'<button type="button" class="outline danger" data-remove-photo="'+(i-urls.length)+'">削除</button>':'')+'</div></div>').join('')+(current>=0?'<button type="button" class="outline" data-clear-featured>代表画像を解除</button>':'')+'<p class="note">代表画像は保存済みの写真から選択。JSONバックアップに写真も含まれます。</p></section>'}
function compressPhoto(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(Error('画像ファイルを選んでください'));if(file.size>15*1024*1024)return reject(Error('15MB以下の画像を選んでください'));const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);try{const scale=Math.min(1,1200/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const result=canvas.toDataURL('image/jpeg',0.72);if(result.length>950000)throw Error('圧縮後も大きすぎる画像です');resolve(result)}catch(e){reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('画像を読み込めませんでした'))};img.src=url})}
function featuredPhoto(r){const urls=[...String(r.photoUrls||'').split(/\r?\n/).map(x=>x.trim()).filter(x=>/^https:\/\//i.test(x)),...(Array.isArray(r.localPhotos)?r.localPhotos:[])];return Number.isInteger(r.featuredPhotoIndex)?urls[r.featuredPhotoIndex]||'':''}
function galleryFor(r){const urls=[...String(r.photoUrls||'').split(/\r?\n/).map(x=>x.trim()).filter(x=>/^https:\/\//i.test(x)),...(Array.isArray(r.localPhotos)?r.localPhotos.filter(x=>/^data:image\/jpeg;base64,/.test(x)):[])].slice(0,40);if(!urls.length)return '';return '<section class="section card"><h2>フォトギャラリー（'+urls.length+'枚）</h2><div class="grid">'+urls.map((url,i)=>'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer" aria-label="写真'+(i+1)+'を開く"><img src="'+esc(url)+'" alt="'+esc(r.name)+' 写真'+(i+1)+'" loading="lazy" style="display:block;width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:10px;border:1px solid var(--line)" onerror="this.parentElement.style.display=\'none\'"></a>').join('')+'</div><p class="note">写真をタップすると元画像を開きます。HTTPS画像URLと端末内に保存した写真に対応。</p></section>'}
function recordDetail(){const r=records.find(x=>x.id===editId);if(!r)return '<div class="empty">記録が見つかりません。</div>';const fields=SCHEMAS[r.type].filter(([key,,kind])=>kind!=='textarea'&&kind!=='calculated'&&key!=='coverUrl'&&key!=='mvUrl'&&r[key]!==''&&r[key]!==undefined&&r[key]!==null).map(([key,label])=>{let value=r[key];if(key==='releaseId')value=records.find(x=>x.id===value)?.name||'作品が見つかりません';return '<div class="item"><span class="muted">'+esc(label)+'</span><strong>'+esc(value)+'</strong></div>'}).join('');const url=featuredPhoto(r)||(r.type==='releases'?r.coverUrl:null);const cover=url&&(/^(https:\/\/|data:image\/jpeg;base64,)/i.test(url))?'<img src="'+esc(url)+'" alt="'+esc(r.name)+'の代表画像" loading="lazy" style="display:block;width:min(100%,420px);height:auto;aspect-ratio:4/3;object-fit:cover;border-radius:12px;border:1px solid var(--line);margin:14px 0" onerror="this.style.display=\'none\'">':'';const textBlocks=[['紹介・概要',r.description],['歌詞',r.lyrics],['収録曲メモ',r.tracklist],['経歴・ソロ活動',r.solo]].filter(([,v])=>String(v||'').trim()).map(([name,v])=>'<section class="section card"><h2>'+esc(name)+'</h2><p style="white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8">'+esc(v)+'</p></section>').join('');const links=[['MVを見る',r.mvUrl],['参照元を開く',r.sourceUrl]].filter(([,v])=>/^https?:\/\//i.test(String(v||''))).map(([name,v])=>'<a class="secondary" href="'+esc(v)+'" target="_blank" rel="noopener noreferrer">'+esc(name)+' ↗</a>').join('');const related=details(r);const revenue=r.type==='shows'&&showRevenue(r)!==null?'<section class="section card"><h2>興行収入（概算）</h2><div class="stat">'+new Intl.NumberFormat('ja-JP').format(showRevenue(r))+' 円</div><p class="note">チケット価格と販売枚数、または動員数から算出</p></section>':'';return '<div class="eyebrow">ARCHIVE / '+esc(TYPES[r.type])+'</div><h1>'+esc(r.name)+'</h1><p class="muted">'+esc(date(r)||'日付未設定')+'</p>'+cover+'<div class="toolbar"><button class="primary" data-edit="'+esc(r.id)+'">編集する</button><button class="secondary" data-go="'+esc(r.type)+'">一覧に戻る</button>'+links+'</div><section class="section card"><h2>基本情報</h2>'+(fields||'<p class="muted">詳細情報は未登録です。</p>')+'</section>'+galleryFor(r)+revenue+textBlocks+related}
function validMoney(v){return v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Number(v)>=0}
function parseTicketTiers(text){if(!String(text||'').trim())return [];return String(text).split(/\r?\n/).filter(x=>x.trim()).map(line=>{const parts=line.split(/[,，、\t]/).map(x=>x.trim());return {name:parts[0]||'',price:parts[1],quantity:parts[2],valid:parts.length===3&&Boolean(parts[0])&&validMoney(parts[1])&&validMoney(parts[2])&&Number.isInteger(Number(parts[2]))}})}
function ticketTierState(r){const tiers=parseTicketTiers(r.ticketTiers);if(!tiers.length)return {active:false,valid:true,tiers:[],quantity:0,revenue:0};const valid=tiers.every(x=>x.valid);return {active:true,valid,tiers,quantity:valid?tiers.reduce((n,x)=>n+Number(x.quantity),0):0,revenue:valid?tiers.reduce((n,x)=>n+Number(x.price)*Number(x.quantity),0):0}}
function showRevenue(r){const t=ticketTierState(r);return t.active?(t.valid?t.revenue:null):(validMoney(r.attendance)&&validMoney(r.ticketPrice)?Number(r.attendance)*Number(r.ticketPrice):null)}
function statistics(){const songs=records.filter(r=>r.type==='songs'),releases=records.filter(r=>r.type==='releases'),shows=records.filter(r=>r.type==='shows');const valid=r=>r!==''&&r!==null&&r!==undefined&&Number.isFinite(Number(r))&&Number(r)>=0;const sum=(rows,key)=>rows.reduce((total,r)=>total+(valid(r[key])?Number(r[key]):0),0);const format=n=>new Intl.NumberFormat('ja-JP').format(n);const countFilled=(rows,key)=>rows.filter(r=>valid(r[key])).length;const cards=[['楽曲数',songs.length,'曲'],['作品数',releases.length,'作品'],['ライブ本数',shows.length,'公演'],['作品売上枚数',sum(releases,'sales'),'枚'],['ライブ総動員',sum(shows,'attendance'),'人'],['ライブ興行収入',shows.reduce((total,r)=>total+(showRevenue(r)??0),0),'円']];const years=new Map();for(const r of [...releases,...shows]){const d=String(r.date||'');if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(d))continue;const y=d.slice(0,4),row=years.get(y)||{year:y,releases:0,shows:0};if(r.type==='releases')row.releases++;else row.shows++;years.set(y,row)}const data=[...years.values()].sort((a,b)=>a.year.localeCompare(b.year));const max=Math.max(1,...data.map(x=>Math.max(x.releases,x.shows)));return '<div class="eyebrow">ARCHIVE ANALYTICS</div><h1>活動統計</h1><p class="muted">登録済みの記録から自動集計しています。未入力の売上・動員数は0として合計しますが、入力済み件数も併記します。</p><div class="grid">'+cards.map(([name,n,unit])=>'<div class="card"><div class="eyebrow">'+name+'</div><div class="stat">'+format(n)+'<small style="font-size:14px;margin-left:5px">'+unit+'</small></div></div>').join('')+'</div><section class="section card"><h2>数値データの入力状況</h2><p>売上枚数：'+countFilled(releases,'sales')+' / '+releases.length+'作品</p><p>動員数：'+countFilled(shows,'attendance')+' / '+shows.length+'公演</p><p>興行収入：'+shows.filter(r=>showRevenue(r)!==null).length+' / '+shows.length+'公演</p></section><section class="section card"><h2>年別活動件数</h2>'+(data.length?data.map(x=>'<div style="margin:16px 0"><strong>'+esc(x.year)+'年</strong><div style="margin-top:7px">作品 '+x.releases+'件<div style="height:9px;background:#453526;border-radius:8px"><div style="height:9px;width:'+Math.round(x.releases/max*100)+'%;background:#d4ad72;border-radius:8px"></div></div></div><div style="margin-top:7px">ライブ '+x.shows+'件<div style="height:9px;background:#453526;border-radius:8px"><div style="height:9px;width:'+Math.round(x.shows/max*100)+'%;background:#ad7767;border-radius:8px"></div></div></div></div>').join(''):'<p class="muted">作品やライブの日付を登録すると年別グラフが表示されます。</p>')+'</section><p class="note">売上枚数・動員数・興行収入は席種別チケットの販売枚数 × 価格を優先し、席種未設定時は動員数 × 一律価格で概算します。招待客・手数料などは反映しません。</p>'}
function more(){return `<div class="eyebrow">EXPLORE</div><h1>その他の機能</h1><div class="grid">${[['bands','バンド情報'],['members','メンバー'],['shows','ライブ'],['events','出来事'],['search','全体検索'],['statistics','活動統計'],['settings','設定・バックアップ']].map(([v,n])=>`<div class="card"><h3>${n}</h3><button class="secondary" data-go="${v}">開く →</button></div>`).join('')}</div><section class="section"><div class="card"><h3>開発状況</h3><p>第1段階：基本データ登録・年表・検索・端末内保存・JSONバックアップを実装。</p><p>高度なシミュレーション、画像管理、複数世界線、Excel/PDF出力などは今後追加します。</p></div></section>`}
function formPage(){const type=window.formType||'bands',r=records.find(x=>x.id===editId)||{type};return `<div class="eyebrow">${editId?'EDIT RECORD':'NEW RECORD'}</div><h1>${esc(TYPES[type])}${editId?'を編集':'を登録'}</h1><form id="recordForm" class="form" data-type="${type}">${SCHEMAS[type].map(([key,label,kind,required])=>{let input='';if(kind==='calculated')input=`<input type="text" name="${key}" value="${type==='shows'&&showRevenue(r)!==null?esc(new Intl.NumberFormat('ja-JP').format(showRevenue(r))+' 円'):'未計算（動員数・チケット価格を入力）'}" readonly aria-label="${esc(label)}"><p class="note">動員数 × チケット価格で自動計算します。実際の収支や手数料は含みません。</p>`;else if(kind==='textarea')input=`<textarea name="${key}" ${required?'required':''}>${esc(r[key])}</textarea>`;else if(kind.startsWith('ref:')){const target=kind.slice(4);const choices=records.filter(x=>x.type===target);input=`<select name="${key}" aria-label="${esc(label)}"><option value="">未設定</option>${choices.map(x=>`<option value="${esc(x.id)}" ${r[key]===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${!choices.length?'<p class="note">作品がまだありません。先に「作品」からアルバム・シングルを登録してください。</p>':''}`}else input=`<input type="${kind}" name="${key}" value="${esc(r[key])}" ${required?'required':''}>`;return `<div class="field"><label>${esc(label)}${required?' *':''}</label>${input}</div>`}).join('')}<div class="toolbar"><button class="primary" type="submit">保存する</button><button class="secondary" type="button" data-go="${type}">キャンセル</button>${editId?'<button class="outline danger" type="button" id="deleteRecord">削除</button>':''}</div></form>${type==='shows'?'<p class="note">席種別チケット例：VIP,15000,100（改行して一般,8000,400）。区分を入力すると一律価格より優先して計算します。販売枚数と動員数は別の値です。</p>':''}${editId?details(r):''}${editId&&type==='releases'?trackEditor(r):''}${editId&&type==='shows'?setlistEditor(r):''}${editId?localPhotoEditor(r):''}<p class="note">データはこのブラウザの端末内に保存されます。定期的にJSONバックアップを作成してください。</p>`}
function searchPage(){const years=[...new Set(records.map(r=>String(date(r)).slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort((a,b)=>b.localeCompare(a));return `<div class="eyebrow">GLOBAL SEARCH</div><h1>全アーカイブ横断検索</h1><p class="note">キーワード・記録の種類・年・収録作品を組み合わせて検索できます。</p><input id="globalSearch" class="search" type="search" placeholder="曲名、人物名、作品名、会場名など" aria-label="全体検索"><div class="toolbar"><label>記録の種類 <select id="globalSearchType"><option value="all">すべて</option>${Object.entries(TYPES).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')}</select></label><label>年 <select id="globalSearchYear"><option value="all">すべての年</option>${years.map(y=>'<option value="'+y+'">'+y+'年</option>').join('')}</select></label><label>収録作品（楽曲のみ） <select id="globalSearchRelease"><option value="all">指定なし</option>${records.filter(r=>r.type==='releases').map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name||'名称未設定')+'</option>').join('')}</select></label><label>並び替え <select id="globalSearchSort"><option value="newest">日付の新しい順</option><option value="oldest">日付の古い順</option><option value="name">名前順</option></select></label><label>種類別の表示件数 <select id="globalSearchLimit"><option value="10">10件</option><option value="30" selected>30件</option><option value="0">全件</option></select></label></div><button type="button" class="outline" id="globalSearchReset">検索条件をリセット</button><p id="globalSearchCount" class="note" aria-live="polite"></p><div id="searchResults"></div>`}
function drawGlobalSearch(){const input=$('globalSearch');if(!input)return;const q=input.value.trim().toLocaleLowerCase(),type=$('globalSearchType').value,year=$('globalSearchYear').value,release=$('globalSearchRelease').value;const matches=records.filter(r=>(type==='all'||r.type===type)&&(year==='all'||String(date(r)).slice(0,4)===year)&&(release==='all'||r.type==='songs'&&r.releaseId===release)&&(!q||Object.entries(r).some(([k,v])=>k!=='id'&&k!=='localPhotos'&&k!=='photoUrls'&&typeof v==='string'&&v.toLocaleLowerCase().includes(q)))).sort((a,b)=>{const sort=$('globalSearchSort').value;if(sort==='name')return title(a).localeCompare(title(b),'ja');const cmp=String(date(a)).localeCompare(String(date(b)));return (sort==='oldest'?cmp:-cmp)||title(a).localeCompare(title(b),'ja')});$('globalSearchCount').textContent='検索結果：'+matches.length+'件 / 全'+records.length+'件';$('globalSearchReset').disabled=!q&&type==='all'&&year==='all'&&release==='all'&&$('globalSearchSort').value==='newest'&&$('globalSearchLimit').value==='30';$('searchResults').innerHTML=Object.entries(TYPES).filter(([t])=>type==='all'||t===type).map(([t,label])=>{const group=matches.filter(r=>r.type===t);return '<section class="section card"><h2>'+label+'（'+group.length+'件）</h2>'+(group.length?listItems(Number($('globalSearchLimit').value)===0?group:group.slice(0,Number($('globalSearchLimit').value)))+(Number($('globalSearchLimit').value)>0&&group.length>Number($('globalSearchLimit').value)?'<p class="note">'+Number($('globalSearchLimit').value)+'件を表示中 / 該当'+group.length+'件。全件表示も選べます。</p>':''):'<p class="note">該当する記録はありません。</p>')+'</section>'}).join('');attachResultButtons();attachEmptyArchiveAction()}
function missingBackupLinks(incoming,existing,mode){const finalRecords=mode==='置換'?incoming:[...existing.filter(r=>!incoming.some(n=>n.id===r.id)),...incoming];const ids=new Set(finalRecords.filter(r=>r.type==='releases').map(r=>r.id));return finalRecords.filter(r=>r.type==='songs'&&r.releaseId&&!ids.has(r.releaseId)).map(r=>r.name+' → '+r.releaseId)}
function importHistory(){try{const h=JSON.parse(localStorage.getItem('band-import-history')||'[]');return Array.isArray(h)?h.slice(0,20):[]}catch(e){return []}}
function saveImportHistory(entry){try{const h=importHistory();h.unshift(entry);localStorage.setItem('band-import-history',JSON.stringify(h.slice(0,20)))}catch(e){console.warn('Import history not saved',e)}}
function exportImportHistoryCsv(visibleOnly=false){const h=visibleOnly?filteredImportHistory().map(item=>item.x):importHistory();if(!h.length){toast('書き出す履歴がありません');return}const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const rows=[['日時','ファイル名','読み込み方法','追加・復元件数','重複件数'],...h.map(x=>[x.when,x.file,x.mode,x.count||0,x.duplicates||0])];const csv='\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n');const name='band-import-history-'+(visibleOnly?'filtered-':'')+new Date().toISOString().slice(0,10)+'.csv';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('読み込み履歴のCSV保存を開始しました')}
function filteredImportHistory(){const h=importHistory(),q=String($('importHistorySearch')?.value||'').trim().toLocaleLowerCase(),mode=$('importHistoryMode')?.value||'all';const sort=$('importHistorySort')?.value||'newest';const rows=h.map((x,i)=>({x,i})).filter(({x})=>(!q||String(x.file||'').toLocaleLowerCase().includes(q))&&(mode==='all'||x.mode===mode));if(sort==='oldest')rows.sort((a,b)=>b.i-a.i);else if(sort==='count-desc')rows.sort((a,b)=>Number(b.x.count||0)-Number(a.x.count||0)||a.i-b.i);return rows}
function importHistorySummary(rows){const count=rows.length,items=rows.reduce((n,{x})=>n+(Number(x.count)||0),0),duplicates=rows.reduce((n,{x})=>n+(Number(x.duplicates)||0),0);return '<div class="import-history-summary"><div><strong>'+count+'</strong><span>読み込み回数</span></div><div><strong>'+items+'</strong><span>追加・復元件数の合計</span></div><div><strong>'+duplicates+'</strong><span>重複件数の合計</span></div></div>'}
function importHistoryRows(){const h=importHistory(),rows=filteredImportHistory();const count=$('importHistoryCount');if(count)count.textContent=rows.length+' / '+h.length+'件';const summary=$('importHistorySummary');if(summary)summary.innerHTML=importHistorySummary(rows);const list=$('importHistoryResults');if(list)list.innerHTML=rows.length?rows.map(({x,i})=>'<li><strong>'+esc(x.when)+'</strong>　'+esc(x.mode)+'<div>'+esc(x.file)+'</div><small>追加・復元：'+Number(x.count||0)+'件 / 重複：'+Number(x.duplicates||0)+'件</small><button type="button" class="outline import-history-delete" data-history-index="'+i+'">この履歴を削除</button></li>').join(''):'<li class="note">該当する履歴はありません。</li>';attachImportHistoryDelete()}
function attachImportHistoryDelete(){document.querySelectorAll('[data-history-index]').forEach(btn=>btn.onclick=()=>{const i=Number(btn.dataset.historyIndex),h=importHistory();if(!Number.isInteger(i)||i<0||i>=h.length)return;if(!confirm('この読み込み履歴を1件削除しますか？\\n活動記録と表紙設定は変更されません。'))return;try{h.splice(i,1);localStorage.setItem('band-import-history',JSON.stringify(h));render();toast('履歴を1件削除しました')}catch(e){toast('履歴を削除できませんでした')}})}
function importHistoryHtml(){const h=importHistory();return '<div class="card section"><h3>バックアップ読み込み履歴</h3><p class="note">この端末の直近20件を表示します。履歴はバックアップに含まれません。</p>'+(h.length?'<div class="toolbar"><button type="button" class="secondary" id="exportImportHistory">全件CSV保存</button><button type="button" class="secondary" id="exportFilteredImportHistory">表示中をCSV保存</button><button type="button" class="outline" id="clearImportHistory">履歴をすべて削除</button></div><div class="import-history-filters"><input id="importHistorySearch" type="search" placeholder="ファイル名で検索" aria-label="ファイル名で検索"><select id="importHistoryMode" aria-label="読み込み方法"><option value="all">すべて</option><option value="追加">追加</option><option value="置換">置換</option></select><select id="importHistorySort" aria-label="履歴の並び替え"><option value="newest">新しい順</option><option value="oldest">古い順</option><option value="count-desc">記録件数が多い順</option></select><span id="importHistoryCount">'+h.length+' / '+h.length+'件</span></div><div id="importHistorySummary">'+importHistorySummary(h.map((x,i)=>({x,i})))+'</div><ul id="importHistoryResults" class="import-history-list">'+h.map((x,i)=>'<li><strong>'+esc(x.when)+'</strong>　'+esc(x.mode)+'<div>'+esc(x.file)+'</div><small>追加・復元：'+Number(x.count||0)+'件 / 重複：'+Number(x.duplicates||0)+'件</small><button type="button" class="outline import-history-delete" data-history-index="'+i+'">この履歴を削除</button></li>').join('')+'</ul>':'<p class="note">読み込み履歴はまだありません。</p>')+'</div>'}

function storedDataIntegrity(){const releases=new Set(records.filter(r=>r.type==='releases').map(r=>r.id));return records.filter(r=>r.type==='songs'&&r.releaseId&&!releases.has(r.releaseId))}
function integrityPanel(){const broken=storedDataIntegrity();return '<div class="card section"><h3>登録済みデータの整合性</h3><p class="note">楽曲の収録作品が現在のデータに存在するか確認します。確認によって記録は変更されません。</p>'+(broken.length?'<p><strong>参照先が見つからない楽曲：'+broken.length+'件</strong></p><ul class="import-history-list">'+broken.map(r=>'<li><strong>'+esc(r.name)+'</strong><div class="note">収録作品ID：'+esc(r.releaseId)+'</div><button type="button" class="secondary" data-integrity-detail="'+esc(r.id)+'">楽曲の詳細を見る</button> <button type="button" class="primary" data-integrity-edit="'+esc(r.id)+'">紐づけを修正</button></li>').join('')+'</ul>':'<p>✓ 収録作品の参照エラーは見つかりませんでした。</p>')+'</div>'}
const BACKUP_ATTEMPT_KEY='band-history-backup-attempt-v1';function backupAttemptStatus(){let raw=null;try{raw=localStorage.getItem(BACKUP_ATTEMPT_KEY)}catch(e){}if(!raw)return 'この端末ではバックアップの書き出し記録がありません。大切なデータは定期的にJSON保存してください。';const time=Date.parse(raw);if(!Number.isFinite(time))return 'バックアップ記録を確認できません。JSON保存をおすすめします。';const days=Math.max(0,Math.floor((Date.now()-time)/86400000));return '最後にバックアップの書き出しを開始：'+new Date(time).toLocaleString('ja-JP')+'（'+days+'日前）'+(days>=7?'。7日以上経過しています。再度バックアップをおすすめします。':'。※ファイルの保存完了は端末側でご確認ください。')}function recordBackupAttempt(){try{localStorage.setItem(BACKUP_ATTEMPT_KEY,new Date().toISOString())}catch(e){}const el=$('backupAttemptStatus');if(el)el.textContent=backupAttemptStatus()}
function settings(){return `<div class="eyebrow">PREFERENCES & DATA</div><h1>設定・データ管理</h1><div class="card"><h3>データのバックアップ</h3><p>全${records.length}件の登録データをJSONファイルに保存できます。</p><p class="note" id="backupAttemptStatus" role="status">'+esc(backupAttemptStatus())+'</p><div class="toolbar"><button class="primary" id="exportJson">JSONを書き出す</button><label class="secondary" for="importJson" style="cursor:pointer">JSONを読み込む</label><input type="file" id="importJson" accept=".json,application/json" hidden></div><p class="note">読み込み時に「追加」または「置換」を選べます。確認画面が表示されます。</p></div><div class="card section"><h3>全アーカイブCSV一括保存</h3><p class="note">6種類のCSVを1つのZIPにまとめます。画像は含みません。</p><button type="button" class="primary" id="exportAllZip">ZIPの内容を確認</button><div id="allZipPreview" class="bulk-song-preview" hidden></div></div>${importHistoryHtml()}${integrityPanel()}<div class="card section"><h3>保存場所</h3><p>このブラウザのIndexedDBに保存しています。ブラウザデータの削除や端末の故障で消える可能性があります。</p><p class="note">アプリはオンライン接続を前提としています。ホーム画面への追加はブラウザの共有メニューから行えます。</p></div><div class="card section"><h3>アプリ情報</h3><p>Band History Archive · Prototype 0.14.4</p><p class="note">データ形式 v1 / GitHub Pages対応 / 外部サーバーへのデータ送信なし</p></div>`}
function archiveResultsHtml(rows){if(rows.length)return listItems(rows);return '<div class="empty">'+(records.some(r=>r.type===view)?'条件に一致する記録がありません。検索語や年・分類を変更してください。':'まだ記録がありません。新規登録から追加できます。')+'<div style="margin-top:12px"><button type="button" class="outline" id="resetEmptyArchive">'+(records.some(r=>r.type===view)?'検索条件をすべて解除':'新規登録へ')+'</button></div></div>'}function attachEmptyArchiveAction(){const b=$('resetEmptyArchive');if(b)b.onclick=()=>{if(records.some(r=>r.type===view)){filter='';archiveYear='';archiveFacet='';archiveSort='date-desc';render()}else{window.formType=view;view='form';render()}}}function updateArchiveResults(){if(!TYPES[view])return;const rows=archiveFiltered(view);$('listResults').innerHTML=archiveResultsHtml(archiveLimit==='all'?rows:rows.slice(0,Number(archiveLimit)));attachEmptyArchiveAction();const showAll=$('showAllArchive');if(showAll){const remaining=archiveLimit==='all'?0:Math.max(0,rows.length-Number(archiveLimit));showAll.hidden=remaining===0;showAll.disabled=remaining===0;showAll.textContent=remaining>0?'残り'+remaining+'件をすべて表示':'残りをすべて表示';showAll.setAttribute('aria-label',remaining>0?'残り'+remaining+'件の検索結果をすべて表示':'検索条件に一致する残りの記録をすべて表示');showAll.title=remaining>0?'現在の検索条件を維持して残り'+remaining+'件を表示':'現在の検索・絞り込み条件を維持して全件表示';}const count=$('archiveCount');if(count)count.textContent=Math.min(rows.length,archiveLimit==='all'?Infinity:Number(archiveLimit))+'件表示 / 一致'+rows.length+'件 / 全'+records.filter(r=>r.type===view).length+'件'+(archiveLimit!=='all'&&rows.length>Number(archiveLimit)?'（残り'+(rows.length-Number(archiveLimit))+'件・下の「残りをすべて表示」ボタンから確認できます）':'');attachResultButtons()}
function yearsForReport(){const years=[...new Set(timelineEntries().map(x=>x.when.slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse();return years.includes(reportYear)?reportYear:years[0]}
